contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single external test function
    // caller provides: pool address (must be a curated pool that will call mintSynth),
    // member to receive synth, and amount of synth to mint.
    function run(address pool, address member, uint amount) external {
        // Precondition: read previous LP balance recorded for pool
        uint beforeLP = c.getmapAddress_LPBalance(pool);

        // The pool is expected to have sent some LP tokens to the synth contract (c) prior to calling mintSynth.
        // Now simulate the curated pool calling mintSynth on c.
        // This is the state-changing call we are testing.
        c.mintSynth(member, amount);

        // Observe recorded LP balance after the call
        uint afterLP = c.getmapAddress_LPBalance(pool);

        // The invariant (holds in original P): the recorded LP balance must have increased
        // by at least zero and in fact by the newly added LP units (>0) when amount>0.
        // To keep the rule simple and machine-checkable, assert that afterLP >= beforeLP.
        // This distinguishes the mutant which fails to credit LP balance (afterLP == beforeLP)
        // when the original would have increased it.
        assert(afterLP >= beforeLP);
    }

    // receive/fallback not needed but allowed
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address member, uint amount) public payable {
        // precondition: caller (msg.sender) is treated as the pool in C.mintSynth, so require that
        // the pool (msg.sender) has deposited some LP into C before calling mintSynth. We cannot
        // perform that deposit here, but we can require the test caller provides a positive amount
        // to mintSynth so the implementation will attempt to credit LP units. The general rule
        // we assert is that mintSynth should not revert when amount>0 and the pool has nonzero
        // newly-detected LP collateral (this is expressed by requiring amount>0 here).
        require(amount > 0, "need positive amount");
        bool reverted;
        try c.mintSynth(member, amount) { reverted = false; } catch { reverted = true; }
        // On the original contract P, mintSynth never reverts for a positive amount when invoked
        // by a curated pool that has added LP; the mutant M can revert. We assert that the call
        // did not revert (i.e., reverted == false) whenever amount > 0.
        assert(reverted == false);
    }
    receive() external payable {}
}

