    function BASE() external view returns (address){ return address(0); }
    function UTILS() external view returns (address){ return address(0); }
    function DAO() external view returns (address){ return address(this); }
    function RESERVE() external view returns (address){ return address(0); }
    function BOND() external view returns (address){ return address(0); }
    function SYNTHFACTORY() external view returns (address){ return address(0); }
    function POOLFACTORY() external view returns (address){ return poolfactory; }
