    function bondingPeriodSeconds() external returns (uint256){ return 0; }
}

contract DummyPoolFactory {
    mapping(address=>bool) public curated;
    function isCuratedPool(address p) external view returns (bool){ return curated[p]; }
    function addCuratedPool(address p) external { curated[p]=true; }
    function removeCuratedPool(address p) external { curated[p]=false; }
    function setCurated(address p, bool v) external { curated[p]=v; }
}

contract PoolHelper {
    C c;
    constructor(C _c){ c = _c; }
    // noop; PoolHelper simply exists so factory can mark it curated; it doesn't need to implement Pool interface
    function callMint(address member, uint amount) external {
        c.mintSynth(member, amount);
    }
